import fs from 'node:fs/promises';
import { chromium } from 'playwright';
const URL='https://www.statesideqm.com/pages/armored-vehicles-purchase-inquiry?preview_theme_id=158561894555';
const out='cert-armored-vehicles';
async function run(viewport,label){const browser=await chromium.launch({headless:true});const ctx=await browser.newContext({viewport});const page=await ctx.newPage();const row={};try{const r=await page.goto(URL,{waitUntil:'domcontentloaded',timeout:40000});row.http=r?.status()||0;await page.waitForTimeout(1000);row.data=await page.evaluate(()=>{const text=(document.querySelector('#MainContent')?.innerText||'').replace(/\s+/g,' ').trim();return{v3Script:!!document.querySelector('[data-sq-refine-v3]'),v3Sidebar:!!document.querySelector('.sq-refine-v3-sidebar'),hasArmored:/armored\s+vehicles/i.test(text),hasInquiry:/inquiry|purchase/i.test(text),title:document.title};});row.errors=[];if(row.http!==200)row.errors.push('HTTP '+row.http);if(row.data.v3Script||row.data.v3Sidebar)row.errors.push('V3 collection UI present');if(!row.data.hasArmored)row.errors.push('Armored Vehicles content missing');if(!row.data.hasInquiry)row.errors.push('inquiry/purchase content missing');await page.screenshot({path:`${out}/${label}.png`,fullPage:true})}catch(e){row.errors=[String(e)];try{await page.screenshot({path:`${out}/${label}-error.png`,fullPage:true})}catch{}}await ctx.close();await browser.close();return row}
await fs.mkdir(out,{recursive:true});const desktop=await run({width:1440,height:1000},'desktop');const mobile=await run({width:390,height:844},'mobile');const report={desktop,mobile,pass:!(desktop.errors?.length||mobile.errors?.length)};await fs.writeFile(`${out}/report.json`,JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(!report.pass)process.exitCode=1;
